"use client";

import { useEffect, useMemo, useReducer, useRef, useState } from "react";
import { BOARD_ART, USED_STAMP_ART, WALL_ART, cardArtPath, effectArtPath, pieceArtPath } from "./art-assets";
import { CARD_BY_ID, CARDS, FORMATION_BACK_RANK, Card, Formation, GameCommand, GameState, PIECE_LABEL, Piece, PieceType, Side, Square, augmentPieceCandidates, augmentPieceTarget, augmentSquareTargets, augmentSwapTarget, augmentTargetPrompt, cardActivationKind, createGame, hunsukkunDropTargets, isFrozenByMudang, jangdolbaengiDropTargets, legalMoves, matchesPieceTarget, migrateGameState, myosupuriPlanningMoves, palaceLineTargets, pieceRestrictions, reduceGame, restrictionTurnsRemaining, revivablePieces, swapCandidates, totalCost, transformTargetType, trapTargets } from "./game/engine";
import type { RoomSession, RoomSideChoice, RoomView } from "./game/multiplayer";

const FORMATIONS:Formation[]=["귀마","원앙마","면상","양귀마"];
/** 포진은 이름 대신 마·상 배열로 표기한다. 양귀마 → 마상상마 */
const formationLabel=(formation:Formation)=>FORMATION_BACK_RANK[formation].map(piece=>piece==="ma"?"마":"상").join("");
const formationGlyphs=(formation:Formation,side:Side="han")=>{const[a,b,c,d]=FORMATION_BACK_RANK[formation].map(piece=>piece==="ma"?(side==="cho"?"马":"馬"):"象");return `${a} ${b} · ${c} ${d}`};
const CATEGORY_LABEL:Record<string,string>={TRANSFORM:"변신",PROMOTION:"승격",OPENING:"개막",ACTIVE:"액티브",PALACE:"궁·궁성",ANOMALY:"이변",RESTRICT:"제약"};
type Modal="setup"|"test-setup"|"test-cho"|"test-han"|"room-create"|"room-join"|"deck"|"stats"|"rules"|"history"|"end"|"resign"|"feedback"|null;
/** `swap`은 기물 2개, `revive`·`piece-square`는 기물 1개와 도착 칸, `square`는 칸만 고른다. */
type PendingAugment={side:Side;cardIndex:number;kind:"piece"|"myosupuri"|"wall"|"trap"|"palace-line"|"swap"|"revive"|"piece-square"|"square";pieceId?:string;planned?:Square[]};
type ReserveSelection={side:Side;pieceId:string;source:"jangdol"|"hunsuk"};
type UIState={game:GameState;started:boolean;selected?:string;selectedReserve?:ReserveSelection;pendingAugment?:PendingAugment;past:GameState[];future:GameState[];replay:number;modal:Modal;notice?:string};
type Action={type:"START";formations:Record<Side,Formation>;augments:boolean;testMode?:boolean}|{type:"SELECT";id?:string}|{type:"SELECT_RESERVE";reserve?:ReserveSelection}|{type:"TARGET_AUGMENT";pending?:PendingAugment}|{type:"GAME";command:GameCommand;actor:Side}|{type:"CLOCK";elapsedMs:number;actor:Side}|{type:"UNDO"}|{type:"REDO"}|{type:"REPLAY";index:number}|{type:"MODAL";modal:Modal}|{type:"LOAD";game:GameState}|{type:"SYNC";game:GameState;clearInteraction?:boolean}|{type:"ROOM_LOBBY"}|{type:"NOTICE";notice?:string};
const initialGame=createGame({cho:"귀마",han:"원앙마"},false);
function reducer(state:UIState,action:Action):UIState{switch(action.type){
  case"START":return{game:createGame(action.formations,action.testMode?false:action.augments,Date.now(),!!action.testMode),started:true,past:[],future:[],replay:-1,modal:null};
  case"SELECT":return{...state,selected:action.id,selectedReserve:undefined,replay:-1};
  case"SELECT_RESERVE":return{...state,selectedReserve:action.reserve,selected:undefined,pendingAugment:undefined,replay:-1,notice:undefined};
  case"TARGET_AUGMENT":return{...state,pendingAugment:action.pending,selected:undefined,selectedReserve:undefined,replay:-1,notice:undefined};
  case"GAME":{const transition=reduceGame(state.game,action.command,action.actor);if(!transition.accepted)return{...state,notice:transition.error?.message};const activated=transition.events.find(event=>event.type==="AUGMENT_ACTIVATED"),granted=transition.events.find(event=>event.type==="TEST_AUGMENT_GRANTED"),rested=action.command.type==="USE_UIBYEONG_REST"?transition.state.pieces.find(piece=>piece.id===action.command.pieceId):undefined,deployed=transition.events.find(event=>event.type==="PIECE_DEPLOYED");return{...state,game:transition.state,selected:undefined,selectedReserve:undefined,pendingAugment:undefined,past:[...state.past,state.game],future:[],notice:activated&&activated.type==="AUGMENT_ACTIVATED"?`${CARD_BY_ID[activated.cardId].name} 발동`:granted&&granted.type==="TEST_AUGMENT_GRANTED"?`${granted.side==="cho"?"초":"한"} · ${CARD_BY_ID[granted.cardId].name} 추가`:rested?`의병 · ${rested.growth??0}단계`:deployed?"장돌뱅이 봇짐 기물 배치":state.notice,replay:-1,modal:transition.state.winner?"end":state.modal}}
  case"CLOCK":{const transition=reduceGame(state.game,{type:"ADVANCE_CLOCK",elapsedMs:action.elapsedMs},action.actor);if(!transition.accepted)return state;const automaticPick=transition.events.find(event=>event.type==="AUGMENT_PICKED");return{...state,game:transition.state,selected:transition.state.winner?undefined:state.selected,selectedReserve:transition.state.winner?undefined:state.selectedReserve,pendingAugment:transition.state.winner?undefined:state.pendingAugment,notice:automaticPick&&automaticPick.type==="AUGMENT_PICKED"?`선택 시간 종료 · ${CARD_BY_ID[automaticPick.cardId].name} 자동 선택`:state.notice,modal:transition.state.winner?"end":state.modal}}
  case"UNDO":{const prev=state.past.at(-1);return prev?{...state,game:prev,past:state.past.slice(0,-1),future:[state.game,...state.future],selected:undefined,selectedReserve:undefined,pendingAugment:undefined,replay:-1,modal:null}:state}
  case"REDO":{const next=state.future[0];return next?{...state,game:next,past:[...state.past,state.game],future:state.future.slice(1),selected:undefined,selectedReserve:undefined,pendingAugment:undefined,replay:-1}:state}
  case"REPLAY":return{...state,replay:Math.max(-1,Math.min(state.game.moves.length-1,action.index)),selected:undefined,selectedReserve:undefined,pendingAugment:undefined};
  case"MODAL":return{...state,modal:action.modal}; case"LOAD":return{...state,game:migrateGameState(action.game),started:true,past:[],future:[],replay:-1,modal:null,pendingAugment:undefined,selectedReserve:undefined};case"SYNC":return{...state,game:migrateGameState(action.game),started:true,selected:action.clearInteraction?undefined:state.selected,selectedReserve:action.clearInteraction?undefined:state.selectedReserve,pendingAugment:action.clearInteraction?undefined:state.pendingAugment,past:action.game.moves.length>state.game.moves.length?[...state.past,state.game]:state.past,replay:-1,modal:action.game.winner?(state.modal??"end"):state.modal};case"ROOM_LOBBY":return{...state,game:initialGame,started:false,selected:undefined,selectedReserve:undefined,pendingAugment:undefined,past:[],future:[],replay:-1,modal:null};case"NOTICE":return{...state,notice:action.notice};default:return state}}

function costTone(cost:number){return cost<=2.5?"low":cost<=3.5?"mid":cost===4?"high":"gold"}
function formatClock(milliseconds:number){const seconds=Math.max(0,Math.ceil(milliseconds/1000));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,"0")}`}
function StarCost({value}:{value:number}){const whole=Math.floor(value),half=value-whole>=.5,label=`별 ${whole}개${half?" 반":""}`;return <span className="star-cost" role="img" aria-label={label} title={label}>{whole===0&&!half?<span aria-hidden="true">☆</span>:Array.from({length:whole},(_,index)=><span aria-hidden="true" key={index}>⭐</span>)}{half&&<span className="half-star" aria-hidden="true"><i>⭐</i></span>}</span>}
function CardBadges({card,remaining}:{card:Card;remaining?:number}){const kind=cardActivationKind(card);return <span className="card-badges"><i className={`activation-badge ${kind.toLowerCase()}`}>{kind==="ACTIVE"?"액티브":"패시브"}</i>{remaining!==undefined&&<i className="restriction-turns-badge">{remaining}수남음</i>}</span>}
const TRANSFORM_SOURCE:Partial<Record<PieceType,string>>={cha:"차",po:"포",ma:"마",sang:"상",sa:"사",jol:"졸·병",gung:"궁"};
function hasBatchim(value:string){const code=value.charCodeAt(value.length-1)-0xac00;return code>=0&&code<=11171&&code%28!==0}
function CardDescription({card}:{card:Card}){if(card.category!=="TRANSFORM"||!card.basePiece)return <p className="card-description">{card.text}</p>;const source=TRANSFORM_SOURCE[card.basePiece]??PIECE_LABEL.cho[card.basePiece],rest=card.text.slice(card.text.indexOf(".")+1).trim();return <p className="card-description transform-description"><span className="transform-lead">내 <strong>“{source}”</strong>{hasBatchim(source)?"을":"를"} <strong>“{card.name}”</strong>{hasBatchim(card.name)?"으로":"로"} 바꿉니다.</span>{rest&&<span className="transform-detail">{rest}</span>}</p>}
function CardTile({card,onClick,compact=false,flair}:{card:Card;onClick?:()=>void;compact?:boolean;flair?:string}){return <button className={`card-tile tone-${costTone(card.cost)} ${compact?"compact":""} ${flair??""}`} onClick={onClick} disabled={!onClick}>
  <div className="card-cost"><b><StarCost value={card.cost}/></b></div>
  {!compact&&<svg className="card-art" viewBox="0 0 240 240" aria-hidden="true"><image href={cardArtPath(card.id)} width="240" height="240"/></svg>}
  <div className="card-name"><strong>{card.name}</strong>{card.hanja&&<em>{card.hanja}</em>}</div>
  <small><CardBadges card={card}/></small>
  {!compact&&<CardDescription card={card}/>}
  {card.duration&&!compact&&<mark>{card.duration}</mark>}
  {onClick&&!compact&&<span className="pick-label">이 증강 선택</span>}
 </button>}

function pieceMeter(piece:Piece):{value:number;max:number}|null{switch(piece.transformCardId){
  case"geobukseon":return{value:piece.hp??2,max:2};
  case"gongseongtap":return{value:piece.hp??2,max:2};
  case"hongipo":return{value:piece.ammo??3,max:3};
  case"jeoktoma":return{value:Math.min(2,piece.growth??0),max:2};
  case"uibyeong":return{value:piece.growth??0,max:3};
  default:return null;
}}

function PiecePips({piece}:{piece:Piece}){const meter=pieceMeter(piece);if(!meter)return null;const gap=8,start=-gap*(meter.max-1)/2;return <g className={`piece-pips ${piece.side}`} aria-hidden="true"><rect x="-15" y="24" width="30" height="11" rx="5"/>{Array.from({length:meter.max},(_,i)=><circle className={i<meter.value?"filled":""} key={i} cx={start+i*gap} cy="29.5" r="2.6"/>)}</g>}

/** 기물에 걸린 제약 증강을 좌상단에 작은 카드로 쌓아 보여 준다. 누르면 설명이 열린다. */
function RestrictionBadges({rows,onOpen}:{rows:{cardId:string;remaining?:number}[];onOpen:(cardId:string)=>void}){
  if(!rows.length)return null;
  return <g className="restriction-badges">{rows.map((row,index)=>{const card=CARD_BY_ID[row.cardId];if(!card)return null;const badgeX=-56+index*30,badgeY=-58;return <g key={row.cardId} className="restriction-badge" role="button" tabIndex={0} aria-label={`${card.name} 제약${row.remaining!==undefined?` · ${row.remaining}수 남음`:""} 설명 보기`} onClick={event=>{event.stopPropagation();onOpen(row.cardId)}} onKeyDown={event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();event.stopPropagation();onOpen(row.cardId)}}}>
    <rect className="restriction-badge-frame" x={badgeX} y={badgeY} width="30" height="30" rx="4"/>
    <clipPath id={`restriction-clip-${row.cardId}-${index}`}><rect x={badgeX+1.5} y={badgeY+1.5} width="27" height="27" rx="3"/></clipPath>
    <image href={cardArtPath(card.id)} x={badgeX+1.5} y={badgeY+1.5} width="27" height="27" clipPath={`url(#restriction-clip-${row.cardId}-${index})`} preserveAspectRatio="xMidYMid slice"/>
    {row.remaining!==undefined&&<g className="restriction-badge-count"><circle cx={badgeX+25} cy={badgeY+5} r="7.5"/><text x={badgeX+25} y={badgeY+8}>{row.remaining}</text></g>}
    <title>{card.name}{row.remaining!==undefined?` · ${row.remaining}수 남음`:""}</title>
  </g>})}</g>;
}

function Lobby({open}:{open:(modal:Exclude<Modal,"deck"|"stats"|"rules"|"end"|null>)=>void}){return <main className="lobby-shell"><section className="lobby-layout"><header className="lobby-brand"><div className="lobby-seals" aria-hidden="true"><span>楚</span><i/><span>漢</span></div><h1>증강<br/>장기</h1></header><section className="lobby-actions" aria-label="대국 시작 메뉴"><div className="lobby-intro"><span>새 대국</span><strong>어떻게 시작할까요?</strong></div><button className="lobby-local" onClick={()=>open("setup")}><span>01</span><div><strong>로컬 2인 시작</strong><small>한 화면에서 번갈아 둡니다</small></div><b>→</b></button><button className="lobby-test" onClick={()=>open("test-setup")}><span>TEST</span><div><strong>증강 테스트</strong><small>각종 증강들을 실험해 보세요</small></div><b>＋</b></button><div className="lobby-room-actions"><button onClick={()=>open("room-create")}><span>02</span><strong>방 만들기</strong><small>초대 코드를 만듭니다</small></button><button onClick={()=>open("room-join")}><span>03</span><strong>방 참여</strong><small>코드로 입장합니다</small></button></div><p className="lobby-note">각자 10분 · 착수마다 3초 추가 · 증강 선택 60초</p><button className="lobby-feedback" onClick={()=>open("feedback")}>이슈 및 건의사항</button></section></section></main>}

function FeedbackModal({close}:{close:()=>void}){const[title,setTitle]=useState(""),[content,setContent]=useState(""),[busy,setBusy]=useState(false),[message,setMessage]=useState(""),[done,setDone]=useState(false);const submit=async()=>{if(!title.trim()||!content.trim()||busy)return;setBusy(true);setMessage("");try{const response=await fetch("/api/feedback",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({title,content})});const payload=await response.json() as{error?:string};if(!response.ok)throw new Error(payload.error||"등록하지 못했습니다.");setDone(true)}catch(cause){setMessage(cause instanceof Error?cause.message:"등록하지 못했습니다.")}finally{setBusy(false)}};return <div className="modal-backdrop"><section className="modal feedback-modal"><button className="modal-close" onClick={close}>×</button><p className="eyebrow">FEEDBACK</p><h2>이슈 및 건의사항</h2>{done?<><p className="modal-lead">보내주셔서 감사합니다. 검토 후 반영하겠습니다.</p><button className="primary-button" onClick={close}>닫기</button></>:<><p className="modal-lead">버그나 개선 아이디어를 알려주세요.</p><label className="room-field"><span>제목</span><input value={title} onChange={event=>setTitle(event.target.value.slice(0,80))} placeholder="제목을 입력하세요" maxLength={80}/></label><label className="room-field"><span>내용</span><textarea value={content} onChange={event=>setContent(event.target.value.slice(0,4000))} placeholder="내용을 입력하세요" rows={6} maxLength={4000}/></label><button className="primary-button" disabled={!title.trim()||!content.trim()||busy} onClick={submit}>{busy?"보내는 중…":"보내기"}</button>{message&&<p className="room-connection-note error" role="alert">{message}</p>}</>}</section></div>}

async function roomFetch<T>(path:string,token?:string,init?:RequestInit):Promise<T>{const response=await fetch(path,{...init,headers:{"Content-Type":"application/json",...(token?{Authorization:`Bearer ${token}`}:{})}});const payload=await response.json() as T&{error?:string};if(!response.ok)throw new Error(payload.error||"방 서버에 연결하지 못했습니다.");return payload}

function RoomCreateModal({close,enter}:{close:()=>void;enter:(session:RoomSession,room:RoomView)=>void}){const[nickname,setNickname]=useState(""),[busy,setBusy]=useState(false),[message,setMessage]=useState("");const create=async()=>{if(!nickname.trim()||busy)return;setBusy(true);setMessage("");try{const result=await roomFetch<{token:string;room:RoomView}>("/api/rooms",undefined,{method:"POST",body:JSON.stringify({nickname})});enter({code:result.room.code,token:result.token},result.room)}catch(cause){setMessage(cause instanceof Error?cause.message:"방을 만들지 못했습니다.")}finally{setBusy(false)}};return <div className="modal-backdrop"><section className="modal room-entry-modal"><button className="modal-close" onClick={close}>×</button><p className="eyebrow">PRIVATE ROOM · HOST</p><h2>방 만들기</h2><p className="modal-lead">표시할 이름을 정하고 초대 코드를 만드세요.</p><label className="room-field"><span>닉네임</span><input value={nickname} onChange={event=>setNickname(event.target.value.slice(0,12))} placeholder="초나라 장수" maxLength={12} autoComplete="nickname"/></label><button className="primary-button" disabled={!nickname.trim()||busy} onClick={create}>{busy?"만드는 중…":"방 만들기"}</button>{message&&<p className="room-connection-note error" role="alert">{message}</p>}</section></div>}

function RoomJoinModal({close,enter}:{close:()=>void;enter:(session:RoomSession,room:RoomView)=>void}){const[nickname,setNickname]=useState(""),[code,setCode]=useState(""),[busy,setBusy]=useState(false),[message,setMessage]=useState("");const join=async()=>{if(!nickname.trim()||code.length!==6||busy)return;setBusy(true);setMessage("");try{const result=await roomFetch<{token:string;room:RoomView}>(`/api/rooms/${code}/join`,undefined,{method:"POST",body:JSON.stringify({nickname})});enter({code:result.room.code,token:result.token},result.room)}catch(cause){setMessage(cause instanceof Error?cause.message:"방에 참여하지 못했습니다.")}finally{setBusy(false)}};return <div className="modal-backdrop"><section className="modal room-entry-modal"><button className="modal-close" onClick={close}>×</button><p className="eyebrow">PRIVATE ROOM · GUEST</p><h2>방 참여</h2><p className="modal-lead">전달받은 6자리 코드를 입력하세요.</p><label className="room-field"><span>닉네임</span><input value={nickname} onChange={event=>setNickname(event.target.value.slice(0,12))} placeholder="한나라 장수" maxLength={12} autoComplete="nickname"/></label><label className="room-field"><span>방 코드</span><input className="room-code-input" value={code} onChange={event=>{setCode(event.target.value.replace(/[^a-zA-Z2-9]/g,"").toUpperCase().slice(0,6));setMessage("")}} placeholder="A7K9QX" maxLength={6} autoCapitalize="characters"/></label><button className="primary-button" disabled={!nickname.trim()||code.length!==6||busy} onClick={join}>{busy?"입장하는 중…":"방 참여"}</button>{message&&<p className="room-connection-note error" role="alert">{message}</p>}</section></div>}

function RoomLobby({room,busy,message,onSettings,onFormation,onReady,onLeave}:{room:RoomView;busy:boolean;message?:string;onSettings:(sideChoice:RoomSideChoice,augments:boolean)=>void;onFormation:(formation:Formation)=>void;onReady:(ready:boolean)=>void;onLeave:()=>void}){const mine=room.viewerRole==="host"?room.host:room.guest!,theirs=room.viewerRole==="host"?room.guest:room.host,isHost=room.viewerRole==="host";const[copyState,setCopyState]=useState<"idle"|"done"|"fail">("idle");useEffect(()=>{if(copyState==="idle")return;const timer=setTimeout(()=>setCopyState("idle"),1800);return()=>clearTimeout(timer)},[copyState]);const copyCode=async()=>{try{if(!navigator.clipboard)throw new Error("clipboard unavailable");await navigator.clipboard.writeText(room.code);setCopyState("done")}catch{setCopyState("fail")}};return <main className="room-lobby-shell"><section className="room-lobby-card"><header><div><p className="eyebrow">ONLINE ROOM</p><h1>대국 준비</h1></div><button className="text-button" onClick={onLeave}>나가기</button></header><div className="room-code-display"><span>방 코드</span><strong>{room.code}</strong><button className={copyState==="idle"?"":copyState} onClick={()=>void copyCode()} aria-live="polite">{copyState==="done"?"복사됨":copyState==="fail"?"복사 실패":"복사"}</button></div><section className="room-players"><article className={room.host.ready?"ready":""}><span>방장</span><strong>{room.host.nickname}</strong><small>{room.host.ready?"준비 완료":"설정 중"}</small></article><i>대</i><article className={room.guest?.ready?"ready":""}><span>참가자</span><strong>{room.guest?.nickname||"입장 대기 중"}</strong><small>{room.guest?.ready?"준비 완료":room.guest?"준비 전":"코드를 전달하세요"}</small></article></section><section className="room-settings"><div><span>방장 진영</span><div className="room-choice-row">{(["cho","han","random"] as RoomSideChoice[]).map(choice=><button key={choice} disabled={!isHost||busy} className={room.sideChoice===choice?"selected":""} aria-pressed={room.sideChoice===choice} onClick={()=>onSettings(choice,room.augments)}>{choice==="cho"?"초":choice==="han"?"한":"무작위"}</button>)}</div></div><div><span>내 포진</span><div className="room-choice-row room-formation-row">{FORMATIONS.map(choice=><button key={choice} disabled={busy} className={mine.formation===choice?"selected":""} aria-pressed={mine.formation===choice} onClick={()=>onFormation(choice)} title={choice}><strong>{formationLabel(choice)}</strong><small>{formationGlyphs(choice,room.playerSide)}</small></button>)}</div><p className="room-formation-note">{theirs?"상대 포진은 대국이 시작될 때 공개됩니다.":"상대가 입장하면 대국을 시작할 수 있습니다."}</p></div><label className="room-augment-choice" htmlFor="room-augments"><span><b>증강 사용</b><small>시작·10수·20수에 증강을 선택합니다</small></span><input id="room-augments" aria-label="증강 사용" type="checkbox" checked={room.augments} disabled={!isHost||busy} onChange={event=>onSettings(room.sideChoice,event.target.checked)}/></label>{!isHost&&<p>방장이 대국 설정을 정하고 있습니다.</p>}</section><button className={`primary-button room-ready-button ${mine.ready?"is-ready":""}`} disabled={!room.guest||busy} onClick={()=>onReady(!mine.ready)}>{mine.ready?"준비 취소":"준비 완료"}</button>{message&&<p className="room-connection-note error" role="alert">{message}</p>}<footer>두 플레이어가 모두 준비하면 바로 시작합니다.</footer></section></main>}

function JangdolbaengiReserve({game,side,selected,onSelect}:{game:GameState;side:Side;selected?:string;onSelect:(pieceId:string)=>void}){const pieces=game.reserves[side];if(!pieces.length)return null;return <span className="jangdol-reserve" aria-label={`${side==="cho"?"초":"한"} 장돌뱅이가 잡은 말`}><i>봇짐</i>{pieces.map(piece=><button key={piece.id} className={selected===piece.id?"selected":""} disabled={game.turn!==side||!!game.winner||!!game.draft} aria-label={`잡은 ${PIECE_LABEL[side][piece.type]} 배치`} title={`잡은 ${PIECE_LABEL[side][piece.type]} 배치`} onClick={()=>onSelect(piece.id)}><svg viewBox="0 0 100 100" aria-hidden="true"><image href={pieceArtPath(piece)} width="100" height="100"/></svg></button>)}</span>}

function HunsukkunReserve({game,side,selected,onSelect}:{game:GameState;side:Side;selected?:string;onSelect:(pieceId:string)=>void}){const pieces=game.waitingPieces[side];if(!pieces.length)return null;return <span className="jangdol-reserve hunsukkun-reserve" aria-label={`${side==="cho"?"초":"한"} 훈수꾼 대기 말`}><i>대기</i>{pieces.map(piece=>{const unavailable=(piece.availablePly??0)>game.ply;return <button key={piece.id} className={selected===piece.id?"selected":""} disabled={game.turn!==side||!!game.winner||!!game.draft||unavailable} aria-label={`대기 ${PIECE_LABEL[side][piece.type]} 투입${unavailable?" · 다음 내 턴부터 가능":""}`} title={unavailable?"다음 내 턴부터 투입 가능":`대기 ${PIECE_LABEL[side][piece.type]} 투입`} onClick={()=>onSelect(piece.id)}><svg viewBox="0 0 100 100" aria-hidden="true"><image href={pieceArtPath({...piece,side})} width="100" height="100"/></svg></button>})}</span>}

function Board({flipped,game,selected,targeting,targetIds,placingWall,placingTrap,placingPalaceLine,placingReserve,placingSquares,previewMoves,planned,onPiece,onSquare,onLine,onRestriction}:{flipped?:boolean;game:GameState;selected?:string;targeting?:{side:Side;type?:PieceType;types?:PieceType[];excludeKing?:boolean;allowTransformed?:boolean};targetIds?:string[];placingWall?:boolean;placingTrap?:Side;placingPalaceLine?:{side:Side;cardId:string};placingReserve?:{side:Side;source:"jangdol"|"hunsuk"};placingSquares?:Square[];previewMoves?:Square[];planned?:Square[];onPiece:(id:string)=>void;onSquare:(s:Square)=>void;onLine:(line:Square[])=>void;onRestriction:(cardId:string)=>void}){
  const moves=previewMoves??(selected?legalMoves(game,selected):[]);// 온라인에서는 내 진영이 항상 아래쪽에 오도록 화면 좌표만 뒤집는다. 논리 좌표는 그대로다.
  const x=(n:number)=>72+(flipped?8-n:n)*100,y=(n:number)=>972-(flipped?9-n:n)*100;
  const [previewLineIndex,setPreviewLineIndex]=useState<number>();
  const riverSides=(["cho","han"] as Side[]).filter(side=>game.cards[side].some(card=>card.cardId==="dogang"&&card.state!=="inert"));
  const expandedPalaces=(["cho","han"] as Side[]).filter(side=>game.cards[side].some(card=>card.cardId==="gwang-gungseong"&&card.state==="active"));
  const wallTargets:Square[]=placingWall?Array.from({length:90},(_,index)=>({x:index%9,y:Math.floor(index/9)})).filter(square=>!game.walls.some(wall=>wall.x===square.x&&wall.y===square.y)&&!game.jeokgi.some(marker=>marker.x===square.x&&marker.y===square.y)&&!game.pieces.some(piece=>!piece.captured&&!piece.carriedBy&&piece.x===square.x&&piece.y===square.y)):[];
  const boardTrapTargets=placingTrap?trapTargets(game,placingTrap):[];
  const reserveTargets=placingReserve?(placingReserve.source==="jangdol"?jangdolbaengiDropTargets(game,placingReserve.side):hunsukkunDropTargets(game,placingReserve.side)):[];
  const lineTargets=placingPalaceLine?palaceLineTargets(game,placingPalaceLine.side):[];
  const linePath=(points:Square[],cardId?:string,side?:Side)=>{let offsetX=0,offsetY=0;if(cardId==="seongbyeok"){const vertical=points.every(point=>point.x===points[0].x);if(vertical)offsetX=points[0].x<=4?-24:24;else offsetY=side==="cho"?-24:24}return points.map((point,index)=>`${index?"L":"M"} ${x(point.x)+offsetX} ${y(point.y)+offsetY}`).join(" ")};
  const choosePalaceLine=(line:Square[],index:number)=>{if(typeof window!=="undefined"&&window.matchMedia("(max-width: 720px)").matches){setPreviewLineIndex(index);return}onLine(line)};
  const confirmedLine=previewLineIndex===undefined?undefined:lineTargets[previewLineIndex];
  const visiblePieces=[...game.pieces.filter(piece=>!piece.captured&&!piece.carriedBy),...game.pieces.filter(piece=>!piece.captured&&piece.carriedBy)];
  return <><div className="board-shell"><svg viewBox="0 0 944 1044" role="img" aria-label="장기판">
    <image className="board-art" href={BOARD_ART} width="944" height="1044"/>
    {expandedPalaces.map(side=>{const near=side==="cho"?3:6,far=side==="cho"?0:9;return <g key={`expanded-${side}`} className={`expanded-palace ${side}`} aria-hidden="true"><rect x={x(2)} y={Math.min(y(near),y(far))} width={x(6)-x(2)} height={Math.abs(y(near)-y(far))}/><path d={`M ${x(3)} ${y(far)} L ${x(6)} ${y(near)} M ${x(5)} ${y(far)} L ${x(2)} ${y(near)}`}/></g>})}
    {riverSides.map(side=><image key={side} className={`river-effect ${side}`} href={effectArtPath("river",side)} x="72" y="490" width="800" height="64" aria-hidden="true"/>)}
    {game.walls.map(w=><image key={`w${w.x}${w.y}`} className="wall-effect" href={WALL_ART} x={x(w.x)-50} y={y(w.y)-50} width="100" height="100" aria-hidden="true"/>)}
    {game.traps.map((trap,index)=><image key={`trap-${trap.side}-${trap.x}-${trap.y}-${index}`} className={`trap-effect ${trap.side}`} href={effectArtPath("trap",trap.side)} x={x(trap.x)-50} y={y(trap.y)-50} width="100" height="100" aria-hidden="true"/>)}
    {game.palaceStructures.map((structure,index)=><path key={`${structure.cardId}-${structure.side}-${index}`} className={`palace-structure ${structure.cardId} ${structure.side}`} d={linePath(structure.points,structure.cardId,structure.side)} aria-hidden="true"/>)}
    {game.jeokgi.map((marker,index)=>{const peers=game.jeokgi.filter(row=>row.side===marker.side),position=peers.indexOf(marker),opacity=[.34,.62,1].slice(3-peers.length)[position]??1;return <image key={`${marker.side}-${marker.x}-${marker.y}-${index}`} className="jeokgi-effect" href={effectArtPath("jeokgi",marker.side)} x={x(marker.x)-50} y={y(marker.y)-50} width="100" height="100" opacity={opacity} aria-hidden="true"/>})}
    {wallTargets.map(square=><g role="button" tabIndex={0} aria-label={`${String.fromCharCode(97+square.x)}${square.y+1}에 방벽 설치`} key={`wall-${square.x},${square.y}`} className="wall-target" onClick={()=>onSquare(square)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();onSquare(square)}}}><circle cx={x(square.x)} cy={y(square.y)} r="31"/><path d={`M ${x(square.x)-17} ${y(square.y)} H ${x(square.x)+17}`}/></g>)}
    {boardTrapTargets.map(square=><g role="button" tabIndex={0} aria-label={`${String.fromCharCode(97+square.x)}${square.y+1}에 함정 설치`} key={`trap-target-${square.x},${square.y}`} className="trap-target" onClick={()=>onSquare(square)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();onSquare(square)}}}><circle cx={x(square.x)} cy={y(square.y)} r="31"/><path d={`M ${x(square.x)-12} ${y(square.y)-12} L ${x(square.x)+12} ${y(square.y)+12} M ${x(square.x)+12} ${y(square.y)-12} L ${x(square.x)-12} ${y(square.y)+12}`}/></g>)}
    {reserveTargets.map(square=><g role="button" tabIndex={0} aria-label={`${String.fromCharCode(97+square.x)}${square.y+1}에 잡은 기물 배치`} key={`reserve-${square.x},${square.y}`} className="reserve-drop-target" onClick={()=>onSquare(square)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();onSquare(square)}}}><circle cx={x(square.x)} cy={y(square.y)} r="31"/><path d={`M ${x(square.x)-12} ${y(square.y)} H ${x(square.x)+12} M ${x(square.x)} ${y(square.y)-12} V ${y(square.y)+12}`}/></g>)}
    {(placingSquares??[]).map(square=><g role="button" tabIndex={0} aria-label={`${String.fromCharCode(97+square.x)}${square.y+1} 선택`} key={`augment-square-${square.x},${square.y}`} className="reserve-drop-target augment-square-target" onClick={()=>onSquare(square)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();onSquare(square)}}}><circle cx={x(square.x)} cy={y(square.y)} r="31"/><path d={`M ${x(square.x)-12} ${y(square.y)} H ${x(square.x)+12} M ${x(square.x)} ${y(square.y)-12} V ${y(square.y)+12}`}/></g>)}
    {lineTargets.map((line,index)=><path key={`palace-line-preview-${index}`} className={`palace-line-preview ${previewLineIndex===index?"selected":""}`} d={linePath(line,placingPalaceLine?.cardId,placingPalaceLine?.side)} aria-hidden="true"/>)}
    {moves.map(s=><g role="button" tabIndex={0} aria-label={`${String.fromCharCode(97+s.x)}${s.y+1}로 이동`} key={`${s.x},${s.y}`} className="move-target" onClick={()=>onSquare(s)} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();onSquare(s)}}}><circle cx={x(s.x)} cy={y(s.y)} r="31"/><circle cx={x(s.x)} cy={y(s.y)} r="8"/></g>)}
    {planned?.length&&selected&&<path className="myosupuri-path" d={[{x:game.pieces.find(piece=>piece.id===selected)?.x??0,y:game.pieces.find(piece=>piece.id===selected)?.y??0},...planned].map((point,index)=>`${index?"L":"M"} ${x(point.x)} ${y(point.y)}`).join(" ")} aria-hidden="true"/>}
    {visiblePieces.map(p=>{const sourceSide:Side=p.side==="cho"?"han":"cho",selecting=!!targeting||!!targetIds,canTarget=targetIds?targetIds.includes(p.id):!!targeting&&p.side===targeting.side&&(!targeting.type||p.type===targeting.type)&&(!targeting.types||targeting.types.includes(p.type))&&(!targeting.excludeKing||p.type!=="gung")&&(targeting.allowTransformed||!p.transformCardId),mudangFrozen=isFrozenByMudang(game,p.id),warded=!!p.shielded&&p.shielded>0,mounted=!!p.carriedBy,host=mounted?game.pieces.find(candidate=>candidate.id===p.carriedBy):undefined,mountLabel=host?.transformCardId==="gongseongtap"?"공성탑":"역마차";return <g role="button" aria-label={`${p.side==="cho"?"초":"한"} ${PIECE_LABEL[p.side][p.type]}${mounted?` · ${mountLabel} 탑승 중`:canTarget?" · 증강 대상":warded?" · 은신 중이라 잡히지 않음":mudangFrozen?" · 무당에게 얼어 이동 불가":""}`} tabIndex={0} className={`piece ${p.side} ${selected===p.id?"selected":""} ${p.transformCardId?"transformed":""} ${p.hidden?"concealed":""} ${warded?"warded":""} ${mudangFrozen?"frozen":""} ${mounted?"mounted":""} ${canTarget?"augment-target":""} ${selecting&&!canTarget?"augment-ineligible":""}`} key={p.id} transform={mounted?`translate(${x(p.x)+27},${y(p.y)-27}) scale(.62)`:`translate(${x(p.x)},${y(p.y)})`} onClick={()=>onPiece(p.id)} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();onPiece(p.id)}}}>
      <circle className="piece-hit-area" r="50"/>
      <circle className="selection-ring" r="48"/>
      <image className="piece-art" href={pieceArtPath(p)} x="-50" y="-50" width="100" height="100" aria-hidden="true"/>
      <PiecePips piece={p}/>
      {p.frozen&&<image className="status-effect" href={effectArtPath("bind",sourceSide)} x="-50" y="-50" width="100" height="100" aria-hidden="true"/>}
      {mudangFrozen&&<image className="status-effect freeze-effect" href={effectArtPath("freeze",sourceSide)} x="-50" y="-50" width="100" height="100" aria-hidden="true"/>}
      {p.infected&&<image className="status-effect" href={effectArtPath("infect",sourceSide)} x="-50" y="-50" width="100" height="100" aria-hidden="true"/>}
      <RestrictionBadges rows={pieceRestrictions(game,p.id)} onOpen={onRestriction}/>
      <title>{p.transformCardId?CARD_BY_ID[p.transformCardId]?.name||"변형 기물":"일반 기물"}</title>
    </g>})}
    {lineTargets.map((line,index)=><path role="button" tabIndex={0} aria-label={`${placingPalaceLine?.cardId==="seongmun"?"성문":"성벽"} 직선 ${index+1} 지정`} key={`palace-line-hit-${index}`} className="palace-line-hit" d={linePath(line,placingPalaceLine?.cardId,placingPalaceLine?.side)} onClick={()=>choosePalaceLine(line,index)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();choosePalaceLine(line,index)}}}/>)}
  </svg></div>{confirmedLine&&<div className="mobile-palace-confirm" role="group" aria-label="궁성 구조물 설치 확정"><span>선택한 위치에 설치할까요?</span><button onClick={()=>onLine(confirmedLine)}>설치 확정</button></div>}</>}

function SetupModal({close,start,testMode=false}:{close:()=>void;start:(f:Record<Side,Formation>,a:boolean)=>void;testMode?:boolean}){const[cho,setCho]=useState<Formation>("귀마"),[han,setHan]=useState<Formation>("원앙마"),[aug,setAug]=useState(true);return <div className="modal-backdrop"><section className="modal setup-modal"><button className="modal-close" onClick={close}>×</button><p className="eyebrow">{testMode?"AUGMENT LAB":"MATCH CONFIGURATION"}</p><h2>{testMode?"증강 테스트 준비":"새 대국 준비"}</h2><p className="modal-lead">각자 10분으로 시작하며 착수마다 3초가 추가됩니다.</p><div className="formation-grid"><FormationPicker side="cho" value={cho} set={setCho}/><FormationPicker side="han" value={han} set={setHan}/></div>{testMode?<div className="test-setup-note"><b>자유 증강 선택</b><span>대국 중 언제든 초와 한에 원하는 증강을 추가할 수 있습니다.</span></div>:<label className="augment-toggle"><input type="checkbox" checked={aug} onChange={e=>setAug(e.target.checked)}/><span><b>증강 카드 사용</b><small>시작 · 10수 · 20수에 각자 60초 동안 한 장 선택</small></span><i>{aug?"ON":"OFF"}</i></label>}<button className="primary-button" onClick={()=>start({cho,han},aug)}>{testMode?"테스트 대국 시작":"초의 첫 수로 시작"}</button></section></div>}
function FormationPicker({side,value,set}:{side:Side;value:Formation;set:(f:Formation)=>void}){return <div className={`formation-picker ${side}`}><div><span className="seal">{side==="cho"?"楚":"漢"}</span><b>{side==="cho"?"초 포진":"한 포진"}</b></div>{FORMATIONS.map(f=><button key={f} className={f===value?"selected":""} aria-pressed={f===value} onClick={()=>set(f)}><strong>{formationLabel(f)}</strong><small>{formationGlyphs(f,side)}</small></button>)}</div>}

function DraftPublicAugments({game}:{game:GameState}){return <details className="draft-public-augments"><summary>현재 공개된 양쪽 증강 확인</summary><div className="draft-public-grid">{(["cho","han"] as Side[]).map(side=><section className={side} key={side}><b>{side==="cho"?"楚 초":"漢 한"}</b><div>{game.cards[side].length?game.cards[side].map(owned=>{const card=CARD_BY_ID[owned.cardId],remaining=restrictionTurnsRemaining(game,owned.cardId);return <article key={owned.cardId}><svg className="public-augment-thumb" viewBox="0 0 240 240" aria-hidden="true"><image href={cardArtPath(card.id)} width="240" height="240"/></svg><div><strong>{card.name} <CardBadges card={card} remaining={remaining}/> · <StarCost value={card.cost}/></strong><CardDescription card={card}/></div></article>}):<small>아직 없음</small>}</div></section>)}</div></details>}

function DraftModal({game,pick}:{game:GameState;pick:(id:string)=>void}){const[picked,setPicked]=useState<{key:string;id:string}|null>(null);const slotKey=`${game.draft?.side??""}-${game.draft?.slot??""}`;const chosen=picked?.key===slotKey?picked.id:null;if(!game.draft)return null;const title=game.draft.slot===0?"개막":`${game.draft.slot===1?10:20}수`;return <div className="modal-backdrop draft-backdrop"><section className="modal draft-modal"><div className="draft-heading"><p className="eyebrow">AUGMENT DRAFT · {game.draft.side.toUpperCase()}</p><h2>{game.draft.side==="cho"?"초":"한"}의 증강 선택 · {title}</h2><time className="draft-clock" dateTime={`PT${Math.ceil(game.draftClockMs/1000)}S`}>선택 시간 <b>{formatClock(game.draftClockMs)}</b></time><div><span>초 <b><StarCost value={totalCost(game,"cho")}/></b></span><i>판정 비용</i><span>한 <b><StarCost value={totalCost(game,"han")}/></b></span></div></div><DraftPublicAugments game={game}/><div className="draft-cards">{game.draft.choices.map(id=><CardTile key={id} card={CARD_BY_ID[id]} flair={chosen?(chosen===id?"picking":"passed"):undefined} onClick={chosen?undefined:()=>{setPicked({key:slotKey,id});pick(id)}}/>)}</div><p className="draft-note">60초가 지나면 첫 번째 카드가 자동 선택됩니다. 선택 후에는 되돌릴 수 없습니다.</p></section></div>}

/** 상대가 고르는 동안 같은 후보 3장을 실시간으로 보여준다. */
function DraftWatchModal({game}:{game:GameState}){const draft=game.draft;const title=draft?draft.slot===0?"개막":`${draft.slot===1?10:20}수`:"";return <div className="modal-backdrop draft-backdrop"><section className="modal draft-modal draft-watch-modal" role="status"><div className="draft-heading"><p className="eyebrow">AUGMENT DRAFT · {(draft?.side??"").toUpperCase()}</p><h2>{draft?`${draft.side==="cho"?"초":"한"}의 증강 선택 중 · ${title}`:"상대 증강 선택 중"}</h2>{draft&&<time className="draft-clock" dateTime={`PT${Math.ceil(game.draftClockMs/1000)}S`}>남은 시간 <b>{formatClock(game.draftClockMs)}</b></time>}</div>{draft?<><div className="draft-cards draft-watch-cards">{draft.choices.map(id=><CardTile key={id} card={CARD_BY_ID[id]}/>)}</div><p className="draft-note">상대가 이 세 장 중에서 고르는 중입니다. 선택이 끝나면 대국이 자동으로 이어집니다.</p></>:<p className="draft-note">상대가 증강을 고르면 대국이 자동으로 이어집니다.</p>}</section></div>}

/** 어느 쪽이든 증강을 확정하면 짧게 카드를 띄운다. 입력을 막지 않는다. */
function AugmentReveal({side,cardId}:{side:Side;cardId:string}){return <div className="draft-reveal" role="status"><p className="eyebrow">AUGMENT LOCKED</p><strong>{side==="cho"?"초":"한"}의 증강</strong><CardTile card={CARD_BY_ID[cardId]} compact/></div>}

function TestAugmentModal({game,side,pick,close}:{game:GameState;side:Side;pick:(id:string)=>void;close:()=>void}){const[cat,setCat]=useState("ALL"),[cost,setCost]=useState("ALL"),[query,setQuery]=useState("");const owned=new Set(game.cards[side].map(card=>card.cardId)),shown=CARDS.filter(card=>!owned.has(card.id)&&(cat==="ALL"||card.category===cat)&&(cost==="ALL"||card.cost===Number(cost))&&(card.name.includes(query)||card.text.includes(query)));return <div className="modal-backdrop"><section className={`modal deck-modal test-augment-modal ${side}`}><button className="modal-close" onClick={close}>×</button><div className="deck-title"><div><p className="eyebrow">AUGMENT LAB · {side.toUpperCase()}</p><h2>{side==="cho"?"초":"한"}에 증강 추가</h2></div><input aria-label="테스트 증강 검색" placeholder="이름 또는 효과 검색" value={query} onChange={event=>setQuery(event.target.value)}/></div><div className="filters"><button className={cat==="ALL"?"selected":""} onClick={()=>setCat("ALL")}>전체</button>{Object.entries(CATEGORY_LABEL).map(([key,label])=><button className={cat===key?"selected":""} onClick={()=>setCat(key)} key={key}>{label}</button>)}<select value={cost} onChange={event=>setCost(event.target.value)}><option value="ALL">모든 비용</option>{[1,1.5,2,2.5,3,3.5,4,4.5,5].map(value=><option key={value}>{value}</option>)}</select></div><p className="test-picker-note">선택한 증강은 즉시 추가됩니다. 액티브와 변신 증강은 카드 목록에서 발동하세요.</p><div className="deck-count">선택 가능 {shown.length}장</div><div className="card-library">{shown.map(card=><CardTile key={card.id} card={card} onClick={()=>pick(card.id)}/>)}</div></section></div>}

function DeckModal({close}:{close:()=>void}){const[cat,setCat]=useState("ALL"),[cost,setCost]=useState("ALL"),[query,setQuery]=useState("");const shown=CARDS.filter(c=>(cat==="ALL"||c.category===cat)&&(cost==="ALL"||c.cost===Number(cost))&&(c.name.includes(query)||c.text.includes(query)));return <div className="modal-backdrop"><section className="modal deck-modal"><button className="modal-close" onClick={close}>×</button><div className="deck-title"><div><p className="eyebrow">COMPENDIUM · {CARDS.length} CARDS</p><h2>증강 카드 도감</h2></div><input aria-label="카드 검색" placeholder="이름 또는 효과 검색" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="filters"><button className={cat==="ALL"?"selected":""} onClick={()=>setCat("ALL")}>전체</button>{Object.entries(CATEGORY_LABEL).map(([k,v])=><button className={cat===k?"selected":""} onClick={()=>setCat(k)} key={k}>{v}</button>)}<select value={cost} onChange={e=>setCost(e.target.value)}><option value="ALL">모든 비용</option>{[1,1.5,2,2.5,3,3.5,4,4.5,5].map(n=><option key={n}>{n}</option>)}</select></div><div className="deck-count">{shown.length}장</div><div className="card-library">{shown.map(c=><CardTile key={c.id} card={c}/>)}</div></section></div>}

type GameRecord={endTurn:number;endReason:string;winner:Side;cards:{side:Side;cardId:string;slot:number}[];totalCost:Record<Side,number>;moves:string[]};
function loadRecords():GameRecord[]{if(typeof window==="undefined")return[];try{return JSON.parse(localStorage.getItem("augment-janggi-records")||"[]")}catch{return[]}}
function StatsModal({close}:{close:()=>void}){const records=loadRecords(),avg=records.length?records.reduce((n,r)=>n+r.endTurn,0)/records.length:0,judged=records.filter(r=>r.endReason==="judgment"||r.endReason==="deathmatch").length;const picks=new Map<string,{p:number,w:number}>();for(const r of records)for(const c of r.cards){const row=picks.get(c.cardId)||{p:0,w:0};row.p++;if(c.side===r.winner)row.w++;picks.set(c.cardId,row)}const leaders=[...picks].sort((a,b)=>b[1].p-a[1].p).slice(0,8);return <div className="modal-backdrop"><section className="modal stats-modal"><button className="modal-close" onClick={close}>×</button><p className="eyebrow">LOCAL PLAYTEST DATA</p><h2>파일럿 통계</h2><div className="stat-grid"><div><b>{records.length}</b><span>완료 대국</span></div><div><b>{avg.toFixed(1)}</b><span>평균 대국 길이</span></div><div><b>{records.length?Math.round(judged/records.length*100):0}%</b><span>판정 종료 비율</span></div></div><h3>카드 선택 상위</h3>{leaders.length?<div className="leaderboard">{leaders.map(([id,v],i)=><div key={id}><span>{String(i+1).padStart(2,"0")}</span><b>{CARD_BY_ID[id]?.name||id}</b><meter min="0" max={Math.max(...leaders.map(x=>x[1].p))} value={v.p}/><small>{v.p}픽 · 승률 {Math.round(v.w/v.p*100)}%</small></div>)}</div>:<div className="no-data">완료한 대국이 쌓이면 카드별 픽률과 승률이 표시됩니다.</div>}</section></div>}

function RulesModal({close}:{close:()=>void}){return <div className="modal-backdrop"><section className="modal rules-modal"><button className="modal-close" onClick={close}>×</button><p className="eyebrow">QUICK RULES</p><h2>대국 규칙 안내</h2><ol><li><b>각자 10분으로 시작합니다.</b><span>착수를 마치면 사용한 쪽의 남은 시간에 3초가 추가되며, 시간이 먼저 끝나면 패배합니다.</span></li><li><b>증강은 각자 60초 안에 선택합니다.</b><span>시작·10수·20수에 진행하며, 시간이 끝나면 첫 번째 카드가 자동 선택됩니다.</span></li><li><b>궁을 직접 잡으세요.</b><span>장군·멍군, 외통, 자살수 금지가 없습니다.</span></li><li><b>별은 힘이 아니라 비용입니다.</b><span>50 완전수에 끝나지 않으면 누적 ★가 낮은 쪽이 이깁니다.</span></li><li><b>동점이면 연장전입니다.</b><span>8수 동안 졸 이동·포획·액티브 사용이 없으면 기물 점수로 판정합니다.</span></li></ol></section></div>}

function HistoryModal({game,currentMove,select,close}:{game:GameState;currentMove:number;select:(index:number)=>void;close:()=>void}){return <div className="modal-backdrop"><section className="modal history-modal"><button className="modal-close" onClick={close}>×</button><p className="eyebrow">MATCH RECORD</p><h2>대국 기보</h2><p className="history-summary">총 {game.moves.length}수 · 보고 싶은 수를 선택하면 당시 판으로 이동합니다.</p><div className="history-move-list">{game.moves.length?game.moves.map((move,index)=><button className={index===currentMove-1?"current":""} key={`${index}-${move.notation}`} onClick={()=>{select(index);close()}}><span>{String(index+1).padStart(2,"0")}</span><b className={move.side}>{move.side==="cho"?"楚":"漢"}</b><em>{move.notation.replace(/^\d+\. /,"")}</em></button>):<div className="no-data">기록된 수가 없습니다.</div>}</div><button className="primary-button history-live-button" onClick={()=>{select(-1);close()}}>최종 판으로 돌아가기</button></section></div>}

function OwnedAugments({game,side,pending,onInspect}:{game:GameState;side:Side;pending?:PendingAugment;onInspect:(side:Side,index:number)=>void}){const rows=game.cards[side];return <section className={`augment-roster ${side}`}><header><span className="seal">{side==="cho"?"楚":"漢"}</span><b>{side==="cho"?"초":"한"}의 증강</b><small>{game.testMode?`${rows.length}장`:`${rows.length} / 3`}</small></header>{rows.length?<div className="augment-summaries">{rows.map((owned,index)=>{const card=CARD_BY_ID[owned.cardId],isPending=pending?.side===side&&pending.cardIndex===index,isUsed=owned.state==="used",remaining=restrictionTurnsRemaining(game,owned.cardId);return <button type="button" className={`augment-summary ${isPending?"targeting":""} ${isUsed?"used":""}`} key={owned.cardId} aria-haspopup="dialog" aria-label={`${card.name} 설명 열기${isUsed?" · 사용됨":""}`} onClick={()=>onInspect(side,index)}><svg className="augment-thumb" viewBox="0 0 240 240" aria-hidden="true"><image href={cardArtPath(card.id)} width="240" height="240"/></svg><span className="augment-summary-heading"><span><strong>{card.name}</strong><CardBadges card={card} remaining={remaining}/></span><small><StarCost value={card.cost}/></small></span><i className="augment-open-icon" aria-hidden="true">＋</i>{isUsed&&<svg className="used-stamp" viewBox="0 0 187 110" aria-hidden="true"><image href={USED_STAMP_ART} width="187" height="110"/></svg>}</button>})}</div>:<div className="side-empty">아직 선택한 증강이 없습니다.</div>}</section>}

function AugmentDetailModal({game,side,index,pending,playerSide,onActivate,close}:{game:GameState;side:Side;index:number;pending?:PendingAugment;playerSide?:Side;onActivate:(side:Side,index:number)=>void;close:()=>void}){
  useEffect(()=>{const handleKey=(event:KeyboardEvent)=>{if(event.key==="Escape")close()};window.addEventListener("keydown",handleKey);return()=>window.removeEventListener("keydown",handleKey)},[close]);
  const owned=game.cards[side][index],card=owned&&CARD_BY_ID[owned.cardId];
  if(!owned||!card)return null;
  const isTransform=!!transformTargetType(card),pieceTarget=augmentPieceTarget(card),isWall=card.id==="bangbyeok",isTrap=card.id==="hamjeong",isPending=pending?.side===side&&pending.cardIndex===index,target=owned.targetPieceId&&game.pieces.find(piece=>piece.id===owned.targetPieceId),canRest=card.id==="uibyeong"&&owned.state!=="inert"&&!!target&&!target.captured&&(target.growth??0)<3,canUse=owned.state==="ready"||canRest,canActNow=(!playerSide||playerSide===side)&&(game.turn===side||game.testMode&&!canRest),remaining=restrictionTurnsRemaining(game,owned.cardId);
  const actionLabel=isPending?(isWall||isTrap?"위치 선택 중":"기물 선택 중"):canRest?`한 턴 쉬기 ${(target?.growth??0)+1}/3`:isTransform?"변신 대상 선택":pieceTarget?"기물 선택":isTrap?"함정 위치 선택":isWall?"방벽 위치 선택":"지금 발동";
  return <div className="modal-backdrop augment-detail-backdrop"><button type="button" className="augment-detail-dismiss" aria-label="증강 설명 바깥 영역 닫기" onClick={close}/><section className={`modal augment-detail-modal ${side}`} role="dialog" aria-modal="true" aria-labelledby={`augment-detail-${side}-${index}`}><button type="button" className="modal-close" aria-label="증강 설명 닫기" onClick={close}>×</button><div className="augment-detail-heading"><svg className="augment-detail-art" viewBox="0 0 240 240" aria-hidden="true"><image href={cardArtPath(card.id)} width="240" height="240"/></svg><div><small>{side==="cho"?"楚 · 초의 증강":"漢 · 한의 증강"}</small><h2 id={`augment-detail-${side}-${index}`}>{card.name}{card.hanja&&<em>{card.hanja}</em>}</h2><div><CardBadges card={card} remaining={remaining}/><StarCost value={card.cost}/></div></div></div><CardDescription card={card}/>{card.duration&&<p className="augment-duration">지속 · {card.duration}</p>}{canUse&&<button className="activate-button augment-detail-action" disabled={!canActNow} onClick={()=>{onActivate(side,index);close()}}>{actionLabel}</button>}</section></div>
}

/** 판 위 제약 배지를 눌렀을 때 뜨는 설명. 어느 쪽 증강인지와 남은 수를 함께 보여 준다. */
function RestrictionInfoModal({game,cardId,close}:{game:GameState;cardId:string;close:()=>void}){
  useEffect(()=>{const handleKey=(event:KeyboardEvent)=>{if(event.key==="Escape")close()};window.addEventListener("keydown",handleKey);return()=>window.removeEventListener("keydown",handleKey)},[close]);
  const card=CARD_BY_ID[cardId],remaining=restrictionTurnsRemaining(game,cardId);
  const owner=(["cho","han"] as Side[]).find(side=>game.cards[side].some(owned=>owned.cardId===cardId));
  return <div className="modal-backdrop augment-detail-backdrop"><button type="button" className="augment-detail-dismiss" aria-label="설명 바깥 영역 닫기" onClick={close}/><section className={`modal augment-detail-modal ${owner??""}`} role="dialog" aria-modal="true" aria-labelledby={`restriction-info-${cardId}`}><button type="button" className="modal-close" aria-label="설명 닫기" onClick={close}>×</button><div className="augment-detail-heading"><svg className="augment-detail-art" viewBox="0 0 240 240" aria-hidden="true"><image href={cardArtPath(card.id)} width="240" height="240"/></svg><div><small>{owner==="cho"?"楚 · 초가 건 제약":owner==="han"?"漢 · 한이 건 제약":"제약"}</small><h2 id={`restriction-info-${cardId}`}>{card.name}{card.hanja&&<em>{card.hanja}</em>}</h2><div><CardBadges card={card} remaining={remaining}/><StarCost value={card.cost}/></div></div></div><CardDescription card={card}/>{card.duration&&<p className="augment-duration">지속 · {card.duration}{remaining!==undefined?` · ${remaining}수 남음`:""}</p>}</section></div>;
}

function AugmentPanel({game,pending,playerSide,onActivate,onTestAdd}:{game:GameState;pending?:PendingAugment;playerSide?:Side;onActivate:(side:Side,index:number)=>void;onTestAdd:(side:Side)=>void}){const[detail,setDetail]=useState<{side:Side;index:number}>();return <aside className="panel augment-panel" id="augment-panel">{game.testMode&&<div className="test-mode-toolbar"><div><b>증강 테스트 모드</b><small>원하는 진영에 증강을 추가하세요.</small></div><button className="cho" onClick={()=>onTestAdd("cho")}>초 증강 추가</button><button className="han" onClick={()=>onTestAdd("han")}>한 증강 추가</button></div>}<div className="all-augments"><OwnedAugments game={game} side="cho" pending={pending} onInspect={(side,index)=>setDetail({side,index})}/><OwnedAugments game={game} side="han" pending={pending} onInspect={(side,index)=>setDetail({side,index})}/></div><div className="judgment-box"><div><span>50수 판정까지</span><b>{Math.max(0,50-game.fullMove)}수</b></div><div className="progress"><i style={{width:`${Math.min(100,game.fullMove*2)}%`}}/></div>{game.deathmatch&&<p>연장전 · 정체 게이지 {game.deathmatchClock}/8</p>}</div>{detail&&<AugmentDetailModal game={game} side={detail.side} index={detail.index} pending={pending} playerSide={playerSide} onActivate={onActivate} close={()=>setDetail(undefined)}/>}</aside>}

function snapshotAtMove(game:GameState,past:GameState[],moveIndex:number){if(moveIndex<0)return game;const moveCount=moveIndex+1;if(game.moves.length===moveCount)return game;for(let index=past.length-1;index>=0;index--)if(past[index].moves.length===moveCount)return past[index];return game}

export default function GameApp(){const[state,dispatch]=useReducer(reducer,{game:initialGame,started:false,past:[],future:[],replay:-1,modal:null});const[online,setOnline]=useState<{session:RoomSession;room:RoomView}|null>(null),[roomBusy,setRoomBusy]=useState(false),[roomMessage,setRoomMessage]=useState("");const recorded=useRef(""),clockMarker=useRef(0),promptedTraps=useRef(new Set<string>());const source=snapshotAtMove(state.game,state.past,state.replay);/* 로컬 대국은 한 화면을 함께 보므로 가려진 기물도 남겨 두고 흐리게만 표시한다. 온라인은 서버가 이미 상대 시야를 걸러 보낸다. */
 const display=source;const selectedMoves=useMemo(()=>state.selected?legalMoves(display,state.selected):[],[state.selected,display]);const pendingOwned=state.pendingAugment&&state.game.cards[state.pendingAugment.side][state.pendingAugment.cardIndex],pendingCard=pendingOwned&&CARD_BY_ID[pendingOwned.cardId],pendingTarget=pendingCard?augmentPieceTarget(pendingCard):undefined,planningMoves=state.pendingAugment?.kind==="myosupuri"&&state.pendingAugment.pieceId?myosupuriPlanningMoves(display,state.pendingAugment.pieceId,state.pendingAugment.planned??[]):undefined,selectedReservePiece=state.selectedReserve&&(state.selectedReserve.source==="jangdol"?state.game.reserves[state.selectedReserve.side]:state.game.waitingPieces[state.selectedReserve.side]).find(piece=>piece.id===state.selectedReserve?.pieceId);const clockSide=state.game.draft?.side??state.game.turn,playerSide=online?.room.playerSide;
 /* 대상 후보와 도착 칸은 모두 엔진이 계산해 UI 강조와 서버 검증이 어긋나지 않게 한다. */
 const pendingKind=state.pendingAugment?.kind,pendingSide=state.pendingAugment?.side,pendingPieceId=state.pendingAugment?.pieceId;
 const augmentTargetIds=useMemo(()=>{
  if(!state.pendingAugment||!pendingCard||!pendingSide)return undefined;
  if(pendingKind==="swap")return swapCandidates(state.game,pendingSide,pendingCard,pendingPieceId?"second":"first",pendingPieceId).map(piece=>piece.id);
  if(pendingKind==="piece"||pendingKind==="piece-square"&&!pendingPieceId)return augmentPieceCandidates(state.game,pendingSide,pendingCard).map(piece=>piece.id);
  return undefined;
 },[state.pendingAugment,state.game,pendingCard,pendingKind,pendingSide,pendingPieceId]);
 const augmentSquares=useMemo(()=>{
  if(!pendingCard||!pendingSide)return undefined;
  const ready=pendingKind==="square"||(pendingKind==="revive"||pendingKind==="piece-square")&&!!pendingPieceId;
  return ready?augmentSquareTargets(state.game,pendingSide,pendingCard):undefined;
 },[state.game,pendingCard,pendingKind,pendingSide,pendingPieceId]);
 const revivableChoices=pendingKind==="revive"&&pendingSide?revivablePieces(state.game,pendingSide):[];
 const[restrictionInfo,setRestrictionInfo]=useState<string|null>(null);
 const applyRoom=(room:RoomView,clearInteraction=false)=>{setOnline(current=>current?{...current,room}:current);if(room.game)dispatch({type:"SYNC",game:room.game,clearInteraction});else dispatch({type:"ROOM_LOBBY"})};
 const enterRoom=(session:RoomSession,room:RoomView)=>{sessionStorage.setItem("augment-janggi-room",JSON.stringify(session));setOnline({session,room});setRoomMessage("");dispatch({type:"MODAL",modal:null});if(room.game)dispatch({type:"SYNC",game:room.game,clearInteraction:true})};
 const leaveRoom=()=>{sessionStorage.removeItem("augment-janggi-room");setOnline(null);setRoomMessage("");dispatch({type:"ROOM_LOBBY"})};
 const roomAction=async(path:string,init:RequestInit,clearInteraction=false)=>{if(!online||roomBusy)return;setRoomBusy(true);setRoomMessage("");try{const result=await roomFetch<{room:RoomView}>(`/api/rooms/${online.session.code}${path}`,online.session.token,init);applyRoom(result.room,clearInteraction)}catch(cause){setRoomMessage(cause instanceof Error?cause.message:"방 요청을 처리하지 못했습니다.");try{const latest=await roomFetch<{room:RoomView}>(`/api/rooms/${online.session.code}`,online.session.token);applyRoom(latest.room,true)}catch{void 0}}finally{setRoomBusy(false)}};
 const sendGame=(command:GameCommand,actor:Side)=>{if(!online){dispatch({type:"GAME",command,actor});return}if(actor!==online.room.playerSide){dispatch({type:"NOTICE",notice:"내 진영의 차례에만 행동할 수 있습니다."});return}void roomAction("/command",{method:"POST",body:JSON.stringify({expectedRevision:online.room.revision,command})},true)};
 useEffect(()=>{const raw=sessionStorage.getItem("augment-janggi-room");if(!raw)return;try{const session=JSON.parse(raw) as RoomSession;roomFetch<{room:RoomView}>(`/api/rooms/${session.code}`,session.token).then(result=>enterRoom(session,result.room)).catch(()=>sessionStorage.removeItem("augment-janggi-room"))}catch{sessionStorage.removeItem("augment-janggi-room")}},[]);
 const onlineSession=online?.session;
 useEffect(()=>{if(!onlineSession)return;let stopped=false,busy=false;const refresh=async()=>{if(stopped||busy)return;busy=true;try{const result=await roomFetch<{room:RoomView}>(`/api/rooms/${onlineSession.code}`,onlineSession.token);if(!stopped)applyRoom(result.room)}catch(cause){if(!stopped)setRoomMessage(cause instanceof Error?cause.message:"방 연결이 끊겼습니다.")}finally{busy=false}};const timer=window.setInterval(refresh,1_000);return()=>{stopped=true;window.clearInterval(timer)}},[onlineSession]);
 useEffect(()=>{if(online)return;if(state.started)localStorage.setItem("augment-janggi-save",JSON.stringify(state.game));if(state.game.winner){const sig=`${state.game.moves.length}-${state.game.winner}`;if(recorded.current!==sig){recorded.current=sig;const records=loadRecords();records.push({endTurn:state.game.fullMove,endReason:state.game.endReason||"capture_king",winner:state.game.winner,cards:(["cho","han"] as Side[]).flatMap(side=>state.game.cards[side].map(c=>({side,cardId:c.cardId,slot:c.slot}))),totalCost:{cho:totalCost(state.game,"cho"),han:totalCost(state.game,"han")},moves:state.game.moves.map(m=>m.notation)});localStorage.setItem("augment-janggi-records",JSON.stringify(records))}}},[state.game,state.started,online]);
 useEffect(()=>{const esc=(e:KeyboardEvent)=>{if(e.key==="Escape"){dispatch({type:"MODAL",modal:null});dispatch({type:"TARGET_AUGMENT"});dispatch({type:"SELECT_RESERVE"})}};window.addEventListener("keydown",esc);return()=>window.removeEventListener("keydown",esc)},[]);
 useEffect(()=>{if(!state.notice)return;const timer=window.setTimeout(()=>dispatch({type:"NOTICE"}),1_000);return()=>window.clearTimeout(timer)},[state.notice]);
 const boardFlipped=!!online&&playerSide==="han";
 const canResign=state.started&&!state.game.winner&&(!online||!!playerSide);
 const resignSide:Side=playerSide??state.game.turn;
 const[reveal,setReveal]=useState<{side:Side;cardId:string}|null>(null);
 const seenAugments=useRef<Record<Side,string[]>|null>(null);
 useEffect(()=>{const current:Record<Side,string[]>={cho:state.game.cards.cho.map(card=>card.cardId),han:state.game.cards.han.map(card=>card.cardId)};const previous=seenAugments.current;seenAugments.current=current;if(!previous)return;for(const side of ["cho","han"] as Side[]){const added=current[side].find(id=>!previous[side].includes(id));if(added){setReveal({side,cardId:added});return}}},[state.game.cards]);
 useEffect(()=>{if(!reveal)return;const timer=setTimeout(()=>setReveal(null),2400);return()=>clearTimeout(timer)},[reveal]);
 useEffect(()=>{if(!state.started||state.pendingAugment||state.game.draft)return;for(const side of(playerSide?[playerSide]:["cho","han"] as Side[])){const index=state.game.cards[side].findIndex(card=>card.cardId==="hamjeong"&&card.state==="ready");const key=`${state.game.rngSeed}-${side}-${index}`;if(index>=0&&!promptedTraps.current.has(key)){promptedTraps.current.add(key);dispatch({type:"TARGET_AUGMENT",pending:{side,cardIndex:index,kind:"trap"}});break}}},[state.started,state.pendingAugment,state.game.draft,state.game.cards,state.game.rngSeed,playerSide]);
 useEffect(()=>{clockMarker.current=Date.now();if(online||!state.started||state.game.winner)return;const timer=window.setInterval(()=>{const now=Date.now(),elapsedMs=now-clockMarker.current;clockMarker.current=now;dispatch({type:"CLOCK",elapsedMs,actor:clockSide})},1_000);return()=>window.clearInterval(timer)},[state.started,state.game.winner,clockSide,online]);
 const addPlannedMove=(square:Square)=>{const pending=state.pendingAugment;if(pending?.kind!=="myosupuri"||!pending.pieceId||(pending.planned?.length??0)>=3||!planningMoves?.some(candidate=>candidate.x===square.x&&candidate.y===square.y))return;dispatch({type:"TARGET_AUGMENT",pending:{...pending,planned:[...(pending.planned??[]),square]}})};
 const handlePiece=(id:string)=>{if(state.replay>=0||state.selectedReserve||state.pendingAugment?.kind==="wall"||state.pendingAugment?.kind==="trap"||state.pendingAugment?.kind==="palace-line"||state.pendingAugment?.kind==="revive"||state.pendingAugment?.kind==="square")return;const p=display.pieces.find(p=>p.id===id);if(!p)return;if(state.pendingAugment?.kind==="piece"){sendGame({type:"USE_AUGMENT",cardIndex:state.pendingAugment.cardIndex,targetPieceId:id},state.pendingAugment.side);return}
  if(state.pendingAugment?.kind==="swap"){const pending=state.pendingAugment;if(!swapCandidates(state.game,pending.side,CARD_BY_ID[state.game.cards[pending.side][pending.cardIndex].cardId],pending.pieceId?"second":"first",pending.pieceId).some(candidate=>candidate.id===id))return;if(!pending.pieceId){dispatch({type:"TARGET_AUGMENT",pending:{...pending,pieceId:id}});return}sendGame({type:"USE_AUGMENT",cardIndex:pending.cardIndex,targetPieceIds:[pending.pieceId,id]},pending.side);return}
  if(state.pendingAugment?.kind==="piece-square"){const pending=state.pendingAugment;const card=CARD_BY_ID[state.game.cards[pending.side][pending.cardIndex].cardId];if(!matchesPieceTarget(p,augmentPieceTarget(card)!,pending.side))return;dispatch({type:"TARGET_AUGMENT",pending:{...pending,pieceId:id}});return}if(state.pendingAugment?.kind==="myosupuri"){if(state.pendingAugment.pieceId){addPlannedMove({x:p.x,y:p.y});return}const side=state.pendingAugment.side;if(p.side===side&&p.type!=="gung"&&!p.captured&&!p.carriedBy)dispatch({type:"TARGET_AUGMENT",pending:{...state.pendingAugment,pieceId:id,planned:[]}});return}if(state.selected&&selectedMoves.some(s=>s.x===p.x&&s.y===p.y)){sendGame({type:"MOVE_PIECE",pieceId:state.selected,to:{x:p.x,y:p.y}},display.turn);return}if(p.side===display.turn&&(!playerSide||p.side===playerSide))dispatch({type:"SELECT",id})};
 const handleActivate=(side:Side,index:number)=>{if(playerSide&&side!==playerSide)return;const owned=state.game.cards[side][index],card=owned&&CARD_BY_ID[owned.cardId];if(card?.id==="uibyeong"&&owned.state!=="inert"&&owned.targetPieceId){sendGame({type:"USE_UIBYEONG_REST",pieceId:owned.targetPieceId},side);return}if(card?.id==="myosupuri"){dispatch({type:"TARGET_AUGMENT",pending:{side,cardIndex:index,kind:"myosupuri",planned:[]}});return}if(card&&augmentSwapTarget(card)){dispatch({type:"TARGET_AUGMENT",pending:{side,cardIndex:index,kind:"swap"}});return}if(card?.id==="buhwal"){dispatch({type:"TARGET_AUGMENT",pending:{side,cardIndex:index,kind:"revive"}});return}if(card&&augmentSquareTargets(state.game,side,card)){dispatch({type:"TARGET_AUGMENT",pending:{side,cardIndex:index,kind:augmentPieceTarget(card)?"piece-square":"square"}});return}if(card&&augmentPieceTarget(card)){dispatch({type:"TARGET_AUGMENT",pending:{side,cardIndex:index,kind:"piece"}});return}if(card?.id==="bangbyeok"){dispatch({type:"TARGET_AUGMENT",pending:{side,cardIndex:index,kind:"wall"}});return}if(card?.id==="hamjeong"){dispatch({type:"TARGET_AUGMENT",pending:{side,cardIndex:index,kind:"trap"}});return}if(card?.id==="seongbyeok"||card?.id==="seongmun"){dispatch({type:"TARGET_AUGMENT",pending:{side,cardIndex:index,kind:"palace-line"}});return}sendGame({type:"USE_AUGMENT",cardIndex:index},side)};
 const handleSquare=(s:Square)=>{if(state.replay>=0)return;if(state.selectedReserve){sendGame({type:state.selectedReserve.source==="jangdol"?"DEPLOY_JANGDOLBAENGI_RESERVE":"DEPLOY_HUNSUKKUN_RESERVE",reservePieceId:state.selectedReserve.pieceId,to:s},state.selectedReserve.side);return}if(state.pendingAugment?.kind==="wall"||state.pendingAugment?.kind==="trap"||state.pendingAugment?.kind==="square"){sendGame({type:"USE_AUGMENT",cardIndex:state.pendingAugment.cardIndex,targetSquare:s},state.pendingAugment.side);return}
  if((state.pendingAugment?.kind==="revive"||state.pendingAugment?.kind==="piece-square")&&state.pendingAugment.pieceId){sendGame({type:"USE_AUGMENT",cardIndex:state.pendingAugment.cardIndex,targetPieceId:state.pendingAugment.pieceId,targetSquare:s},state.pendingAugment.side);return}if(state.pendingAugment?.kind==="myosupuri"){addPlannedMove(s);return}if(state.pendingAugment)return;if(state.selected)sendGame({type:"MOVE_PIECE",pieceId:state.selected,to:s},display.turn)};const handleReserve=(side:Side,pieceId:string,source:"jangdol"|"hunsuk")=>{if(playerSide&&side!==playerSide)return;dispatch({type:"SELECT_RESERVE",reserve:state.selectedReserve?.side===side&&state.selectedReserve.pieceId===pieceId&&state.selectedReserve.source===source?undefined:{side,pieceId,source}})};const currentMove=state.replay>=0?state.replay+1:display.moves.length;
 const confirmMyosupuri=()=>{const pending=state.pendingAugment;if(pending?.kind!=="myosupuri"||!pending.pieceId||(pending.planned?.length??0)!==3)return;sendGame({type:"USE_AUGMENT",cardIndex:pending.cardIndex,targetPieceId:pending.pieceId,targetSquares:pending.planned},pending.side)};
 const handleLine=(line:Square[])=>{if(state.replay>=0||state.pendingAugment?.kind!=="palace-line")return;sendGame({type:"USE_AUGMENT",cardIndex:state.pendingAugment.cardIndex,targetLine:line},state.pendingAugment.side)};
 if(online&&!online.room.game)return <RoomLobby room={online.room} busy={roomBusy} message={roomMessage} onSettings={(sideChoice,augments)=>void roomAction("/settings",{method:"PATCH",body:JSON.stringify({sideChoice,augments})})} onFormation={formation=>void roomAction("/formation",{method:"PATCH",body:JSON.stringify({formation})})} onReady={ready=>void roomAction("/ready",{method:"POST",body:JSON.stringify({ready})})} onLeave={leaveRoom}/>;
 if(!state.started)return <><Lobby open={modal=>dispatch({type:"MODAL",modal})}/>{state.modal==="setup"&&<SetupModal close={()=>dispatch({type:"MODAL",modal:null})} start={(formations,augments)=>dispatch({type:"START",formations,augments})}/>} {state.modal==="test-setup"&&<SetupModal testMode close={()=>dispatch({type:"MODAL",modal:null})} start={(formations,augments)=>dispatch({type:"START",formations,augments,testMode:true})}/>} {state.modal==="room-create"&&<RoomCreateModal close={()=>dispatch({type:"MODAL",modal:null})} enter={enterRoom}/>} {state.modal==="room-join"&&<RoomJoinModal close={()=>dispatch({type:"MODAL",modal:null})} enter={enterRoom}/>} {state.modal==="feedback"&&<FeedbackModal close={()=>dispatch({type:"MODAL",modal:null})}/>}</>;
 const playerName=(side:Side)=>{if(!online?.room.hostSide)return side==="cho"?"초록":"빨강";return online.room.hostSide===side?online.room.host.nickname:online.room.guest?.nickname||"참가자"};
 return <main className="app-frame">
  <header className="topbar"><button className="brand" onClick={()=>dispatch({type:"MODAL",modal:null})}><h1>증강 장기</h1>{state.game.testMode&&<i className="test-mode-mark">TEST</i>}</button><div className="turn-readout"><span>초 <b><StarCost value={totalCost(display,"cho")}/></b></span><i>{state.started?`${display.fullMove}수 · ${display.turn==="cho"?"초":"한"} 차례`:"준비"}</i><span>한 <b><StarCost value={totalCost(display,"han")}/></b></span></div><nav>{canResign&&<button className="resign-button" onClick={()=>dispatch({type:"MODAL",modal:"resign"})}>기권</button>}<button onClick={()=>dispatch({type:"MODAL",modal:"rules"})}>규칙</button><button onClick={()=>dispatch({type:"MODAL",modal:"stats"})}>통계</button><button onClick={()=>dispatch({type:"MODAL",modal:"deck"})}>도감</button><button className="ghost-button" onClick={()=>online?navigator.clipboard?.writeText(online.room.code):dispatch({type:"MODAL",modal:"setup"})}>{online?`방 ${online.room.code}`:"새 대국"}</button><details className="mobile-nav-menu"><summary>메뉴</summary><div><button onClick={event=>{event.currentTarget.closest('details')?.removeAttribute('open');document.getElementById('augment-panel')?.scrollIntoView({behavior:'smooth',block:'start'})}}>증강 확인</button>{canResign&&<button className="resign-button" onClick={event=>{event.currentTarget.closest('details')?.removeAttribute('open');dispatch({type:"MODAL",modal:"resign"})}}>기권</button>}{([['history','기보'],['rules','규칙'],['stats','통계'],['deck','증강 도감']] as const).map(([modal,label])=><button key={modal} onClick={event=>{event.currentTarget.closest('details')?.removeAttribute('open');dispatch({type:"MODAL",modal})}}>{label}</button>)}{online?<button onClick={event=>{event.currentTarget.closest('details')?.removeAttribute('open');navigator.clipboard?.writeText(online.room.code)}}>방 코드 복사</button>:<button onClick={event=>{event.currentTarget.closest('details')?.removeAttribute('open');dispatch({type:"MODAL",modal:"setup"})}}>새 대국</button>}</div></details></nav></header>
  {state.notice&&<button className="toast" onClick={()=>dispatch({type:"NOTICE"})}>{state.notice}<span>×</span></button>}
  {state.replay>=0&&<div className="mobile-replay-bar" role="status"><span>기보 {currentMove} / {state.game.moves.length}</span><button onClick={()=>dispatch({type:"REPLAY",index:-1})}>최종 판으로</button></div>}
  <section className="game-layout"><aside className="panel history-panel"><div className="panel-heading"><span>기보</span><small>{state.replay>=0?"REPLAY":online?"ONLINE":"LIVE"}</small></div><div className="move-list">{state.game.moves.length?state.game.moves.map((m,i)=><button className={i===currentMove-1?"current":""} key={`${i}${m.notation}`} onClick={()=>dispatch({type:"REPLAY",index:i})}><span>{m.side==="cho"?"楚":"漢"}</span>{m.notation.replace(/^\d+\. /,"")}</button>):<div className="empty-state"><strong>첫 수를 기다리는 중</strong><p>교차점의 기물을 선택하면<br/>갈 수 있는 길이 표시됩니다.</p></div>}</div><div className="history-controls"><button onClick={()=>dispatch({type:"REPLAY",index:0})}>↤</button><button onClick={()=>dispatch({type:"REPLAY",index:state.replay<0?state.game.moves.length-1:state.replay-1})}>←</button><span>{currentMove} / {state.game.moves.length}</span><button onClick={()=>dispatch({type:"REPLAY",index:state.replay+1>=state.game.moves.length-1?-1:state.replay+1})}>→</button><button onClick={()=>dispatch({type:"REPLAY",index:-1})}>↦</button></div>{!online&&<div className="save-actions"><button disabled={!state.past.length} onClick={()=>dispatch({type:"UNDO"})}>무르기</button><button disabled={!state.future.length} onClick={()=>dispatch({type:"REDO"})}>다시 두기</button><button onClick={()=>{const raw=localStorage.getItem("augment-janggi-save");if(raw)dispatch({type:"LOAD",game:JSON.parse(raw)})}}>저장 대국 불러오기</button></div>}</aside>
   <section className="table-area">
    <div className={`player-strip han ${!display.draft&&display.turn==="han"?"clock-active":""}`}><span className="seal">漢</span><div><div className="player-identity"><b>한 · {playerName("han")}</b><JangdolbaengiReserve game={display} side="han" selected={state.selectedReserve?.side==="han"&&state.selectedReserve.source==="jangdol"?state.selectedReserve.pieceId:undefined} onSelect={pieceId=>handleReserve("han",pieceId,"jangdol")}/><HunsukkunReserve game={display} side="han" selected={state.selectedReserve?.side==="han"&&state.selectedReserve.source==="hunsuk"?state.selectedReserve.pieceId:undefined} onSelect={pieceId=>handleReserve("han",pieceId,"hunsuk")}/></div><small>{!display.draft&&display.turn==="han"?"차례":""}</small></div><div className="player-metrics"><time dateTime={`PT${Math.ceil(display.clocks.han/1000)}S`}>{formatClock(display.clocks.han)}</time><strong><StarCost value={totalCost(display,"han")}/></strong></div></div>
    {selectedReservePiece&&state.selectedReserve?<div className="targeting-banner reserve-targeting-banner" role="status"><span><b>{PIECE_LABEL[state.selectedReserve.side][selectedReservePiece.type]}</b>을 놓을 {state.selectedReserve.source==="jangdol"?"내 궁성 안":"내 진영"} 빈칸을 선택하세요.</span><button onClick={()=>dispatch({type:"SELECT_RESERVE"})}>취소</button></div>:pendingCard&&state.pendingAugment&&<div className="targeting-banner" role="status"><span>{state.pendingAugment.kind==="wall"?<><b>{pendingCard.name}</b>을 세울 빈 교차점을 선택하세요.</>:state.pendingAugment.kind==="trap"?<><b>{pendingCard.name}</b>을 설치할 내 궁성 안 빈칸을 선택하세요.</>:state.pendingAugment.kind==="palace-line"?<><b>{pendingCard.name}</b>으로 지정할 궁성 직선을 선택하세요.</>:state.pendingAugment.kind==="myosupuri"?<><b>{pendingCard.name}</b> · {state.pendingAugment.pieceId?`예정 행마 ${state.pendingAugment.planned?.length??0}/3`:"원하는 내 말 선택"}</>:state.pendingAugment.kind==="swap"?<><b>{pendingCard.name}</b> · {state.pendingAugment.pieceId?"위치를 맞바꿀 두 번째 기물을 선택하세요.":pendingCard.id==="daeyeok"?"내 궁을 선택한 뒤 맞바꿀 사를 고르세요.":"위치를 맞바꿀 첫 기물을 선택하세요."}</>:state.pendingAugment.kind==="revive"?<><b>{pendingCard.name}</b> · {state.pendingAugment.pieceId?"되살릴 기물을 놓을 내 궁성 안 빈칸을 선택하세요.":revivableChoices.length?"되살릴 기물을 고르세요.":"되살릴 수 있는 잡힌 기물이 없습니다."}</>:state.pendingAugment.kind==="piece-square"?<><b>{pendingCard.name}</b> · {state.pendingAugment.pieceId?"옮길 빈칸을 선택하세요.":augmentTargetPrompt(pendingCard,state.pendingAugment.side)}</>:state.pendingAugment.kind==="square"?<><b>{pendingCard.name}</b> · {pendingCard.id==="bonghwa"?"궁을 옮길 내 궁성 안 빈칸을 선택하세요.":"궁을 옮길 내 진영 빈칸을 선택하세요."}</>:pendingTarget&&<><b>{pendingCard.name}</b> · {augmentTargetPrompt(pendingCard,state.pendingAugment.side)}</>}</span>{state.pendingAugment.kind==="revive"&&!state.pendingAugment.pieceId&&<span className="revive-choices">{revivableChoices.map(piece=><button key={piece.id} aria-label={`${PIECE_LABEL[piece.side][piece.type]} 되살리기`} title={PIECE_LABEL[piece.side][piece.type]} onClick={()=>dispatch({type:"TARGET_AUGMENT",pending:{...state.pendingAugment!,pieceId:piece.id}})}><svg viewBox="0 0 100 100" aria-hidden="true"><image href={pieceArtPath(piece)} width="100" height="100"/></svg></button>)}</span>}{(state.pendingAugment.kind==="myosupuri"||state.pendingAugment.kind==="swap"||state.pendingAugment.kind==="revive"||state.pendingAugment.kind==="piece-square")&&state.pendingAugment.pieceId&&<button onClick={()=>dispatch({type:"TARGET_AUGMENT",pending:{...state.pendingAugment!,pieceId:undefined,planned:[]}})}>다시 선택</button>}{state.pendingAugment.kind==="myosupuri"&&(state.pendingAugment.planned?.length??0)===3&&<button className="confirm-plan" onClick={confirmMyosupuri}>3수 확정</button>}<button onClick={()=>dispatch({type:"TARGET_AUGMENT"})}>취소</button></div>}
    <Board flipped={boardFlipped} key={state.pendingAugment?.kind==="palace-line"?`palace-line-${state.pendingAugment.side}-${state.pendingAugment.cardIndex}`:"board"} game={display} selected={state.pendingAugment?.kind==="myosupuri"||state.pendingAugment?.kind==="swap"||state.pendingAugment?.kind==="piece-square"?state.pendingAugment.pieceId:state.selected} targetIds={augmentTargetIds} targeting={state.pendingAugment?.kind==="myosupuri"&&!state.pendingAugment.pieceId?{side:state.pendingAugment.side,excludeKing:true,allowTransformed:true}:undefined} placingWall={state.pendingAugment?.kind==="wall"} placingTrap={state.pendingAugment?.kind==="trap"?state.pendingAugment.side:undefined} placingPalaceLine={state.pendingAugment?.kind==="palace-line"&&pendingCard?{side:state.pendingAugment.side,cardId:pendingCard.id}:undefined} placingReserve={selectedReservePiece&&state.selectedReserve?{side:state.selectedReserve.side,source:state.selectedReserve.source}:undefined} placingSquares={augmentSquares} previewMoves={planningMoves??(state.pendingAugment?.kind==="swap"||state.pendingAugment?.kind==="piece-square"?[]:undefined)} planned={state.pendingAugment?.planned} onPiece={handlePiece} onSquare={handleSquare} onLine={handleLine} onRestriction={setRestrictionInfo}/>
    <div className={`player-strip cho ${!display.draft&&display.turn==="cho"?"clock-active":""}`}><span className="seal">楚</span><div><div className="player-identity"><b>초 · {playerName("cho")}</b><JangdolbaengiReserve game={display} side="cho" selected={state.selectedReserve?.side==="cho"&&state.selectedReserve.source==="jangdol"?state.selectedReserve.pieceId:undefined} onSelect={pieceId=>handleReserve("cho",pieceId,"jangdol")}/><HunsukkunReserve game={display} side="cho" selected={state.selectedReserve?.side==="cho"&&state.selectedReserve.source==="hunsuk"?state.selectedReserve.pieceId:undefined} onSelect={pieceId=>handleReserve("cho",pieceId,"hunsuk")}/></div><small>{!display.draft&&display.turn==="cho"?"차례":""}</small></div><div className="player-metrics"><time dateTime={`PT${Math.ceil(display.clocks.cho/1000)}S`}>{formatClock(display.clocks.cho)}</time><strong><StarCost value={totalCost(display,"cho")}/></strong></div></div>
   </section>
   {state.started?<AugmentPanel game={state.game} pending={state.pendingAugment} playerSide={playerSide} onActivate={handleActivate} onTestAdd={side=>dispatch({type:"MODAL",modal:side==="cho"?"test-cho":"test-han"})}/>:<aside className="panel augment-panel lobby-panel"><div className="panel-heading"><span>증강 카드</span><small>{CARDS.length} DECK</small></div><button className="deck-card" onClick={()=>dispatch({type:"MODAL",modal:"deck"})}><span className="deck-star">★</span><strong>카드 도감</strong><small>{CARDS.length}개의 변칙을 살펴보세요</small></button><div className="launch-card"><p>궁을 직접 잡으면 승리합니다.<br/>장군도, 자살수도 없습니다.</p><button className="primary-button" onClick={()=>dispatch({type:"MODAL",modal:"setup"})}>로컬 2인 시작</button></div><div className="rule-note"><span>50</span><p><b>완전수 판정</b><br/>끝나지 않으면 누적 ★가 낮은 쪽이 승리</p></div></aside>}
  </section>
  {!online&&state.modal==="setup"&&<SetupModal close={()=>dispatch({type:"MODAL",modal:null})} start={(formations,augments)=>dispatch({type:"START",formations,augments})}/>} {(state.modal==="test-cho"||state.modal==="test-han")&&<TestAugmentModal game={state.game} side={state.modal==="test-cho"?"cho":"han"} close={()=>dispatch({type:"MODAL",modal:null})} pick={cardId=>{const side=state.modal==="test-cho"?"cho":"han";dispatch({type:"GAME",command:{type:"TEST_GRANT_AUGMENT",side,cardId},actor:state.game.turn});dispatch({type:"MODAL",modal:null})}}/>} {state.modal==="resign"&&<div className="modal-backdrop"><section className="modal resign-modal"><p className="eyebrow">RESIGN</p><h2>기권하시겠습니까?</h2><p className="modal-lead">{resignSide==="cho"?"초":"한"}가 기권하면 대국이 즉시 끝나고 상대의 승리로 기록됩니다. 되돌릴 수 없습니다.</p><button className="primary-button" disabled={roomBusy} onClick={()=>{dispatch({type:"MODAL",modal:null});sendGame({type:"RESIGN"},resignSide)}}>기권하기</button><button className="secondary-button" onClick={()=>dispatch({type:"MODAL",modal:null})}>계속 두기</button></section></div>} {state.modal==="deck"&&<DeckModal close={()=>dispatch({type:"MODAL",modal:null})}/>} {state.modal==="stats"&&<StatsModal close={()=>dispatch({type:"MODAL",modal:null})}/>} {state.modal==="rules"&&<RulesModal close={()=>dispatch({type:"MODAL",modal:null})}/>} {state.modal==="history"&&<HistoryModal game={state.game} currentMove={currentMove} select={index=>dispatch({type:"REPLAY",index})} close={()=>dispatch({type:"MODAL",modal:null})}/>} {state.modal==="end"&&state.game.winner&&<div className="modal-backdrop"><section className="modal end-modal"><p className="eyebrow">MATCH COMPLETE</p><div className={`winner-seal ${state.game.winner}`}>{state.game.winner==="cho"?"楚":"漢"}</div><h2>{state.game.winner==="cho"?"초":"한"} 승리</h2><p>{state.game.endReason==="capture_king"?"상대 궁을 직접 포획했습니다.":state.game.endReason==="special_victory"?"증강의 특수 승리 조건을 달성했습니다.":state.game.endReason==="judgment"?"50수 판정에서 더 낮은 비용을 지켰습니다.":state.game.endReason==="timeout"?"상대의 대국 시간이 먼저 끝났습니다.":state.game.endReason==="resign"?"상대가 기권했습니다.":"연장전 기물 점수 판정에서 앞섰습니다."}</p><div className="end-cost"><span>초 <StarCost value={totalCost(state.game,"cho")}/></span><b>{state.game.fullMove}수</b><span>한 <StarCost value={totalCost(state.game,"han")}/></span></div><button className="primary-button" disabled={roomBusy} onClick={()=>online?void roomAction("/lobby",{method:"POST"},true):dispatch({type:"MODAL",modal:"setup"})}>{online?"방 대기실로":"다음 대국"}</button><button className="text-button" onClick={()=>dispatch({type:"MODAL",modal:"history"})}>기보 보기</button></section></div>}
  {restrictionInfo&&CARD_BY_ID[restrictionInfo]&&<RestrictionInfoModal game={state.game} cardId={restrictionInfo} close={()=>setRestrictionInfo(null)}/>}
  {state.game.draft&&(!online||state.game.draft.side===playerSide)&&<DraftModal game={state.game} pick={id=>sendGame({type:"PICK_AUGMENT",cardId:id},state.game.draft!.side)}/>} {online?.room.draftSide&&online.room.draftSide!==playerSide&&<DraftWatchModal game={state.game}/>} {reveal&&<AugmentReveal side={reveal.side} cardId={reveal.cardId}/>}
 </main>}
